class Solution {
    public int findNonMinOrMax(int[] nums) {
        if (nums.length < 3) return -1;
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        for (int x : nums) { mn = Math.min(mn, x); mx = Math.max(mx, x); }
        for (int x : nums) if (x != mn && x != mx) return x;
        return -1;
    }
}

